document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("plant-spacing-form"),t=document.getElementById("plant-spacing-result"),n=document.getElementById("plant-type"),a=document.getElementById("custom-spacing");n&&n.addEventListener("change",function(){"custom"===this.value?a.style.display="block":a.style.display="none"}),e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("garden-length").value),a=parseFloat(document.getElementById("garden-width").value),s=document.getElementById("plant-type").value,o=document.getElementById("spacing-pattern").value,r=document.getElementById("garden-layout").value,l=parseFloat(document.getElementById("border-space").value);if(n<=0||a<=0)return t.textContent="Please enter valid garden dimensions.",void 0;let p,i;if("custom"===s){if(p=parseFloat(document.getElementById("custom-length").value),i=parseFloat(document.getElementById("custom-width").value),!p||!i||p<=0||i<=0)return t.textContent="Please enter valid custom spacing values.",void 0}else{if(""===s)return t.textContent="Please select a plant type.",void 0;[p,i]=s.split(",").map(Number)}const d=12*n,c=12*a,u=Math.max(0,d-2*l),g=Math.max(0,c-2*l);let h,m,v,f=u,y=g,$="";if("rows"===r){const e=18,t=i,n=Math.floor(g/(t+e));y=n*t,$=`${n} planting rows with 18" paths`}if("square"===o)h=Math.floor(f/p)+1,m=Math.floor(y/i)+1,v=h*m;else{h=Math.floor(f/p)+1,m=Math.floor(y/i)+1;v=Math.ceil(m/2)*h+Math.floor(m/2)*(Math.floor((f-p/2)/p)+1)}const w=n*a,M=u*g/144,b=v/M,E="sqft"===r?Math.floor(M)*Math.floor(144/(p*i)):null;let I="";I="square"===o?`${h} plants × ${m} plants in square grid`:`${m} rows with alternating ${h} and ${Math.floor((f-p/2)/p)+1} plants (triangular pattern)`;"custom"===s||document.getElementById("plant-type").options[document.getElementById("plant-type").selectedIndex].text.split(" (")[0];const x=Math.ceil(1.1*v),B=.1*M,q=.623*(1*M);t.innerHTML=`\n        <div class="result-section">\n          <h4>Garden Layout Results:</h4>\n          <p>Garden size: ${n}' × ${a}' (${w.toFixed(1)} sq ft)</p>\n          <p>Plantable area: ${M.toFixed(1)} sq ft</p>\n          <p>Plant spacing: ${p}" × ${i}"</p>\n          <p>Pattern: ${"square"===o?"Square grid":"Triangular offset"}</p>\n          ${$?`<p>Layout: ${$}</p>`:""}\n        </div>\n        \n        <div class="result-plants">\n          <h4>Plant Count:</h4>\n          <p><strong>${v} total plants</strong></p>\n          <p>${I}</p>\n          <p>Density: ${b.toFixed(2)} plants per sq ft</p>\n          ${E?`<p>Square foot method: ${E} plants</p>`:""}\n        </div>\n        \n        <div class="result-materials">\n          <h4>Materials Needed:</h4>\n          <p><strong>Seeds/Seedlings:</strong> ${x} (includes 10% extra)</p>\n          <p><strong>Mulch:</strong> ${B.toFixed(1)} cubic feet (4" deep)</p>\n          <p><strong>Weekly watering:</strong> ${q.toFixed(1)} gallons</p>\n          <p><strong>Border space:</strong> ${l}" around edges</p>\n        </div>\n        \n        <div class="result-planting">\n          <h4>Planting Instructions:</h4>\n          <p>🌱 Start from one corner, measure ${p}" between plants</p>\n          <p>📏 Space rows ${i}" apart</p>\n          ${"triangular"===o?"<p>🔄 Offset every other row by half the spacing distance</p>":""}\n          <p>💧 Water thoroughly after planting</p>\n          <p>🌿 Apply mulch around plants (avoid touching stems)</p>\n        </div>\n        \n        <div class="result-layout-tips">\n          <h4>Layout Optimization:</h4>\n          <p>📐 Use string lines or measuring tape for straight rows</p>\n          <p>🎯 Mark plant positions with stakes before planting</p>\n          <p>🌞 Orient rows north-south for even sun exposure</p>\n          <p>🚶 Leave 18-24" paths for access and maintenance</p>\n          <p>📏 Consider mature plant size, not seedling size</p>\n        </div>\n        \n        <div class="result-companion">\n          <h4>Companion Planting Tips:</h4>\n          <p>🌿 Herbs can be planted between larger vegetables</p>\n          <p>🥕 Root vegetables work well with leafy greens</p>\n          <p>🌻 Tall plants (tomatoes) pair with short ones (lettuce)</p>\n          <p>🐛 Marigolds can be scattered throughout for pest control</p>\n          <p>🌽 Three Sisters: corn, beans, and squash together</p>\n        </div>\n        \n        <div class="result-timing">\n          <h4>Planting Schedule:</h4>\n          <p>📅 Check frost dates for your area</p>\n          <p>🌱 Start warm-season crops after last frost</p>\n          <p>❄️ Cool-season crops can handle light frost</p>\n          <p>🔄 Succession plant every 2-3 weeks for continuous harvest</p>\n          <p>📋 Keep planting records for future planning</p>\n        </div>\n        \n        <div class="result-maintenance">\n          <h4>Maintenance Requirements:</h4>\n          <p>💧 Water: ${q.toFixed(1)} gallons/week (1" depth)</p>\n          <p>✂️ Space between plants allows air circulation</p>\n          <p>🌿 Mulch maintains moisture and suppresses weeds</p>\n          <p>🔍 Regular spacing improves pest/disease monitoring</p>\n          <p>🌱 Proper spacing reduces competition and stress</p>\n        </div>\n        \n        <div class="result-alternatives">\n          <h4>Alternative Layouts:</h4>\n          <p><strong>Intensive beds:</strong> ${Math.floor(1.15*v)} plants (closer spacing)</p>\n          <p><strong>Container garden:</strong> ${Math.ceil(v/4)} large containers needed</p>\n          <p><strong>Vertical growing:</strong> Use trellises to save 30-50% space</p>\n          <p><strong>Raised beds:</strong> Allow 20% closer spacing than ground level</p>\n        </div>\n      `})});